	private int GetRandomEnemy()
	{
		int num = 0;
		do
		{
			num = UnityEngine.Random.Range(0, MainManager.enemydata.GetLength(0) - 1);
		}
		while (bosslist.Contains(num) || minibosslist.Contains(num) || minibosscard.Contains(num) || num == 47 || (excludeids.Contains(num) && !speciallist.Contains(num)));
		return num;
	}

	public void StartEvent(int id, NPCControl caller)
	{
		MainManager.lastevent = id;
		if (MainManager.pausemenu != null)
		{
			UnityEngine.Object.Destroy(MainManager.pausemenu.gameObject);
		}
		call = caller;
		MainManager.battlelossevent = false;
		if (MainManager.player != null)
		{
			Vector3 zero = Vector3.zero;
			if (call != null)
			{
				zero = call.transform.position;
			}
			else
			{
				MainManager.player.entity.detect.transform.LookAt(MainManager.player.transform.position + MainManager.player.lastdelta);
				zero = MainManager.player.entity.detect.transform.position;
			}
			MainManager.TeleportFollowers(5f, MainManager.TPDir.Away, zero);
			for (int i = 0; i < MainManager.instance.playerdata.Length; i++)
			{
				if (MainManager.instance.playerdata[i].entity != null)
				{
					MainManager.instance.playerdata[i].entity.emoticonoffset = new Vector3(0f, 2f + (float)MainManager.instance.playerdata[i].entity.animid * 0.1f, -0.1f);
					if (MainManager.player.digging)
					{
						StartCoroutine(MainManager.instance.playerdata[i].entity.StopDig());
					}
				}
			}
			MainManager.player.CancelAction();
			MainManager.player.entity.icooldown = 0f;
			if (MainManager.player.entity.model == null)
			{
				MainManager.player.entity.sprite.enabled = true;
			}
			if (MainManager.map.tempfollowers != null && MainManager.map.tempfollowers.Count > 0)
			{
				for (int j = 0; j < MainManager.map.tempfollowers.Count; j++)
				{
					MainManager.map.tempfollowers[j].digging = false;
					MainManager.map.tempfollowers[j].StopForceMove();
				}
			}
		}
		MainManager.instance.discoveryhud = 0f;
		if (MainManager.instance.playerdata != null && MainManager.instance.playerdata.Length != 0)
		{
			for (int k = 0; k < MainManager.instance.playerdata.Length; k++)
			{
				if (MainManager.instance.playerdata[k].entity != null)
				{
					MainManager.instance.playerdata[k].entity.StopForceMove(-1, false);
				}
			}
		}
		MainManager.instance.hudcooldown = 0f;
		MainManager.instance.showmoney = 0f;
		MainManager.instance.camanglespeed = 0.1f;
		MainManager.instance.camanglechange = false;
		MainManager.instance.camoffset2 = Vector3.zero;
		MainManager.instance.inevent = true;
		MainManager.instance.minipause = true;
		MainManager.instance.overridefollower = true;
		MainManager.instance.camspeed = 0.1f;
		MainManager.instance.camoffsetspeed = MainManager.instance.camspeed;
		StartCoroutine("Event" + id);
	}

	private static void EndEvent()
	{
		EndEvent(false);
	}

	private static void EndEvent(bool overridefollower)
	{
		MainManager.instance.camoffsetspeed = 0.1f;
		MainManager.instance.overridefollower = overridefollower;
		MainManager.instance.inevent = false;
		MainManager.player.entity.hitwall = false;
		MainManager.player.entity.emoticoncooldown = 0f;
		MainManager.player.lastdelta = Vector3.zero;
		MainManager.battlelossevent = false;
		MainManager.player.npc.Clear();
		MainManager.player.entity.emoticonid = -1;
		MainManager.player.actioncooldown = 10f;
		MainManager.player.entity.rigid.constraints = RigidbodyConstraints.FreezeRotation;
		bool hologram = MainManager.BadgeIsEquipped(83);
		for (int i = 0; i < MainManager.instance.playerdata.Length; i++)
		{
			MainManager.instance.playerdata[i].entity.hologram = hologram;
			MainManager.instance.playerdata[i].entity.UpdateSpriteMat();
		}
		MainManager.FixEntities();
		MainManager.instance.Invoke("CheckAchievement", 0.5f);
		MainManager.player.pausecooldown = 35f;
		if (MainManager.lastevent != 3)
		{
			MainManager.player.interactcd = 15f;
		}
		MainManager.lastevent = -1;
		MainManager.instance.minipause = false;
		if (destroycaller && call != null)
		{
			UnityEngine.Object.Destroy(call.gameObject);
		}
		destroycaller = false;
		Time.timeScale = 1f;
		MainManager.noskip = false;
		MainManager.instance.skiptext = false;
		MainManager.instance.flagvar[3] = 0;
	}

	private void GiveItem(int type, int id)
	{
		MainManager.instance.StartCoroutine(MainManager.SetText("|giveitem," + type + "," + id + ",-11|", true, Vector3.zero, null, null));
	}

	private void GiveItem(int type, int id, int playerid)
	{
		MainManager.instance.StartCoroutine(MainManager.SetText("|giveitem," + type + "," + id + ",-11," + playerid + "|", true, Vector3.zero, null, null));
	}

	private IEnumerator ArtifactGet(Transform obj, int msgid, EntityControl player)
	{
		while (player.forcemove)
		{
			yield return null;
		}
		player.animstate = 4;
		MainManager.instance.camtarget = null;
		SpriteRenderer tb = MainManager.NewSpriteObject("itemback", player.transform.position + Vector3.forward * 0.25f + Vector3.up * 2.75f, Vector3.zero, null, MainManager.guisprites[85], MainManager.spritedefaultunity);
		tb.color = new Color(0.75f, 0.75f, 0.75f);
		tb.gameObject.AddComponent<DialogueAnim>().SetUp(Vector3.zero, Vector3.one * 2f, Vector3.zero, 0f);
		obj.position = player.transform.position + Vector3.back * 0.05f + Vector3.up * 3f;
		if (MainManager.map.mapid == MainManager.Maps.HoneyFactoryCore)
		{
			obj.transform.localEulerAngles = new Vector3(0f, 0f, -45f);
		}
		MainManager.PlaySound("ItemGetS");
		yield return new WaitForSeconds(2f);
		MainManager.instance.StartCoroutine(MainManager.SetText("|boxstyle,5||noskip||spd,0.125||lockbacktrack||center|" + MainManager.map.dialogues[msgid] + "|fwait,0.75|", true, Vector3.zero, null, null));
		while (MainManager.instance.message)
		{
			yield return null;
		}
		MainManager.FadeIn(0.025f, Color.white);
		yield return null;
		SpriteRenderer dimmer = MainManager.GetTransitionSprite();
		while (dimmer.color.a < 0.95f)
		{
			yield return null;
		}
		yield return new WaitForSeconds(0.75f);
		UnityEngine.Object.Destroy(tb.gameObject);
		UnityEngine.Object.Destroy(obj.gameObject);
		player.animstate = 0;
		yield return new WaitForSeconds(0.75f);
		dimmer.sortingOrder = -10;
		temproutine = null;
	}

	private static Vector3[] SaveMapLimits()
	{
		return new Vector3[2]
		{
			MainManager.map.camlimitpos,
			MainManager.map.camlimitneg
		};
	}

	private static Vector3[] SaveMapLimits(bool Remove)
	{
		Vector3[] result = new Vector3[2]
		{
			MainManager.map.camlimitpos,
			MainManager.map.camlimitneg
		};
		if (Remove)
		{
			RemoveMapLimits();
		}
		return result;
	}

	private static void RemoveMapLimits()
	{
		MainManager.map.camlimitpos = Vector3.one * 999f;
		MainManager.map.camlimitneg = Vector3.one * -999f;
	}

	private static void ReturnMapLimits(Vector3[] maplimits)
	{
		MainManager.map.camlimitpos = maplimits[0];
		MainManager.map.camlimitneg = maplimits[1];
	}

