		yield return null;
		while (MainManager.instance.message)
		{
			yield return null;
		}
		MainManager.instance.camspeed = 0.025f;
		MainManager.instance.camtargetpos = new Vector3(-14f, 0.85f, 4f);
		MainManager.instance.camoffset = new Vector3(0f, 4f);
		MainManager.instance.camangleoffset = new Vector3(20f, -40f);
