	private IEnumerator Event1()
	{
		EntityControl entity = MainManager.GetEntity(4);
		if (entity != null)
		{
			entity.gameObject.SetActive(false);
		}
		MainManager.SaveCameraPosition(true);
		MainManager.PlaySound("RopeSnap", -1, 1.3f, 1f);
		EntityControl[] entities = new EntityControl[2]
		{
			MainManager.GetEntity(-4),
			MainManager.GetEntity(-5)
		};
		entities[0].transform.position = new Vector3(-11.27f, 0.8f, 10.34f);
		entities[1].transform.position = new Vector3(-9.95f, 0.8f, 10.435f);
		for (int i = 0; i < entities.Length; i++)
		{
			entities[i].FaceTowards(entities[i].transform.position - entities[i].transform.right.normalized);
			entities[i].StopForceMove(-1, false);
			entities[i].overrridejump = true;
		}
		Transform[] objs = new Transform[4]
		{
			MainManager.map.mainmesh.GetChild(0),
			MainManager.map.mainmesh.GetChild(1),
			MainManager.map.mainmesh.GetChild(0).GetChild(1),
			MainManager.map.mainmesh.GetChild(0).GetChild(2)
		};
		Vector3[] maplimits = SaveMapLimits();
		RemoveMapLimits();
		MainManager.instance.camtarget = null;
		MainManager.instance.camtargetpos = new Vector3(-15.5f, 1f, -5f);
		MainManager.instance.camangleoffset = default(Vector3);
		MainManager.instance.camspeed = 0.03f;
		float timer = 0f;
		yield return tenthsec;
		while (timer < 1f)
		{
			objs[1].transform.position += objs[1].transform.forward.normalized * 1f;
			timer += MainManager.TieFramerate(0.03f);
			yield return null;
		}
		yield return new WaitForSeconds(1f);
		objs[1].transform.position = new Vector3(0f, 9999f);
		MainManager.halt = true;
		MainManager.PlaySound("Rope1");
		objs[0].GetComponent<Animator>().Play("Fall");
		yield return null;
		while (MainManager.halt)
		{
			yield return null;
		}
		MainManager.SaveCameraPosition(false);
		yield return new WaitForSeconds(1f);
		for (int j = 0; j < entities.Length; j++)
		{
			entities[j].overrridejump = false;
			entities[j].animstate = 0;
		}
		yield return new WaitForSeconds(0.2f);
		MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.map.dialogues[7], true, Vector3.zero, entities[1].transform, null));
		yield return null;
		while (MainManager.instance.message)
		{
			yield return null;
		}
		ReturnMapLimits(maplimits);
		objs[0].GetComponent<Animator>().enabled = false;
		objs[0].transform.localPosition = new Vector3(0.15792f, 0.0148f, 0f);
		MainManager.instance.flags[7] = true;
		MainManager.instance.flags[11] = true;
		yield return null;
		EndEvent();
	}

	private IEnumerator Event2()
	{
		EntityControl[] entities = new EntityControl[2]
		{
			MainManager.GetEntity(-4),
			MainManager.GetEntity(-5)
		};
		entities[1].MoveTowards(new Vector3(36.95f, 0f, -1.12f), 1f, 1, 0, true);
		entities[0].MoveTowards(new Vector3(39f, 0f, 0f), 1f, 1, 0, true);
		entities[0].backsprite = false;
		entities[1].backsprite = false;
		MainManager.instance.camtarget = null;
		MainManager.instance.camtargetpos = new Vector3(38.4f, 0f, 0.85f);
		MainManager.instance.camspeed = 0.02f;
		yield return null;
		while (entities[0].forcemove || entities[1].forcemove)
		{
			yield return null;
		}
		for (int i = 0; i < 4; i++)
		{
			entities[1].flip = !entities[1].flip;
			yield return halfsec;
		}
		MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.map.dialogues[1], true, Vector3.zero, entities[1].transform, null));
		yield return null;
		while (MainManager.instance.message)
		{
			yield return null;
		}
		MainManager.instance.flags[10] = true;
		yield return null;
		MainManager.ResetCamera();
		EndEvent();
	}

	private IEnumerator Event3()
	{
		while (MainManager.instance.message)
		{
			yield return null;
		}
		if (MainManager.instance.flags[119] && !MainManager.instance.flags[120])
		{
			yield return halfsec;
			EntityControl betl = MainManager.GetEntity(-5);
			EntityControl be = MainManager.GetEntity(-4);
			betl.animstate = 17;
			be.FaceTowards(betl.transform.position);
			yield return null;
			MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.map.dialogues[74], true, Vector3.zero, betl.transform, call));
			while (MainManager.instance.message)
			{
				yield return null;
			}
			be.FaceTowards(call.transform.position);
			be.animstate = 112;
			yield return new WaitForSeconds(0.6f);
			be.animstate = 109;
			MainManager.PlaySound("ItemHold");
			SpriteRenderer item = MainManager.NewSpriteObject(be.transform.position + new Vector3(-0.5f, 2.5f, -0.1f), null, MainManager.itemsprites[0, 1]);
			yield return sec;
			UnityEngine.Object.Destroy(item.gameObject);
			be.animstate = 0;
			MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.map.dialogues[75], true, Vector3.zero, be.transform, call));
			while (MainManager.instance.message)
			{
				yield return null;
			}
			be.animstate = 0;
			be.FaceTowards(call.transform.position);
			betl.FaceTowards(call.transform.position);
			MainManager.instance.flagvar[0] = 1;
			MainManager.instance.flagvar[1] = -1;
			MainManager.instance.flags[12] = false;
