		{
			items = new int[2]
			{
				MainManager.instance.flagvar[0],
				MainManager.instance.flagvar[1]
			};
			if (!MainManager.instance.flags[400])
			{
				MainManager.instance.items[0].Remove(MainManager.instance.flagvar[1]);
			}
			MainManager.instance.flagvar[0] = MainManager.MixIngredients(MainManager.instance.flagvar[0], MainManager.instance.flagvar[1]);
