			MainManager.instance.flags[197] = false;
			MainManager.instance.flags[196] = false;
			MainManager.instance.flags[194] = true;
		}
		if (chefid == 1 && MainManager.instance.flags[186] && MainManager.instance.flagvar[0] == 87)
		{
			MainManager.instance.flags[194] = true;
			MainManager.instance.flags[192] = true;
			MainManager.instance.flags[186] = false;
		}
		if (chefid == 2 && MainManager.instance.flags[187] && MainManager.instance.flagvar[0] == 69 && MainManager.instance.flagvar[23] == 0)
		{
			MainManager.instance.flagvar[23]++;
			MainManager.instance.flags[194] = true;
		}
		if (chefid == 2 && MainManager.instance.flags[187] && MainManager.instance.flagvar[0] == 91 && MainManager.instance.flagvar[23] == 1)
		{
			MainManager.instance.flagvar[23]++;
			MainManager.instance.flags[194] = true;
		}
		if (chefid == 2 && MainManager.instance.flags[187] && MainManager.instance.flagvar[0] == 62 && MainManager.instance.flagvar[23] == 2)
		{
			MainManager.instance.flagvar[23]++;
