			while (enemies.Count < 4 && MainManager.instance.flagvar[0] == 1)
			{
				MainManager.instance.flagvar[2] = enemies.Count + 1;
				MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.map.dialogues[65], true, Vector3.zero, ant.transform, ant.npcdata));
				while (MainManager.instance.message)
				{
