				if (MainManager.instance.flagvar[0] == 1)
				{
					enemies.Add(MainManager.instance.flagvar[1]);
				}
			}
			string text = "";
			for (int i = 0; i < enemies.Count; i++)
			{
				text += MainManager.enemynames[enemies[i]];
				if (i < enemies.Count - 2)
				{
					text += ", ";
				}
				else if (i < enemies.Count - 1)
				{
					text += " and ";
				}
			}
			MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.map.dialogues[66] + text + MainManager.map.dialogues[67], true, Vector3.zero, ant.transform, ant.npcdata));
