			{
				MainManager.instance.flags[15] = true;
				MainManager.instance.flags[16] = true;
				MainManager.instance.flags[24] = true;
				MainManager.instance.StartCoroutine(BattleControl.StartBattle(enemies.ToArray(), -1, -1, null, null, false));
			}
		}
		yield return null;
		EndEvent();
		MainManager.player.entity.hitwall = false;
	}

