	public void SamiraStop(NPCControl samira, bool instant)
	{
		if (samira.internaltransform != null && samira.internaltransform[0] != null)
		{
			UnityEngine.Object.Destroy(samira.internaltransform[0].gameObject);
		}
		samira.internaltransform = null;
		if (instant)
		{
			call.entity.overrideanim = true;
			call.entity.animstate = 0;
		}
	}

