			while (MainManager.instance.message)
			{
				yield return null;
			}
			MainManager.instance.flags[43] = true;
			yield return new WaitForSeconds(0.2f);
		}
		if (isplaying)
		{
			MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.commondialogue[36], true, Vector3.zero, call.transform, call));
			while (MainManager.instance.message)
			{
				yield return null;
			}
