				{
					SamiraStop();
					play = -2;
				}
				else
				{
					play = -1;
				}
			}
			else if (MainManager.instance.option == 2)
			{
				SamiraStop();
				play = -2;
			}
		}
		else
		{
			MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.commondialogue[34], true, Vector3.zero, call.transform, call));
			while (MainManager.instance.message)
			{
				yield return null;
			}
			if (!MainManager.listcanceled)
			{
				play = -1;
			}
			else
			{
				SamiraStop();
				play = -2;
			}
		}
		bool buyall = !MainManager.listcanceled && MainManager.listoption < MainManager.listvar.Length && MainManager.listvar[MainManager.listoption] == -1;
		yield return new WaitForSeconds(0.2f);
