		{
			if (buyall || MainManager.instance.samiramusics[MainManager.listoption + (MainManager.listvar.Contains(-1) ? (-1) : 0)][1] == -1)
			{
				int[] missing = MainManager.SamiraMissing();
				if (buyall)
				{
					cost *= missing.Length;
					SamiraStop();
					play = -2;
				}
				MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.commondialogue[buyall ? 153 : 40].Replace("@VALUE@", "|currency," + cost + "|"), true, Vector3.zero, call.transform, call));
				while (MainManager.instance.message)
				{
					yield return null;
				}
				if (MainManager.instance.option == 0)
				{
					if (MainManager.instance.money >= cost)
					{
						MainManager.instance.money -= cost;
						if (buyall)
						{
							for (int i = 0; i < missing.Length; i++)
							{
								int[] item = new int[2]
								{
									MainManager.instance.samiramusics[missing[i]][0],
									1
								};
								MainManager.instance.samiramusics.RemoveAt(missing[i]);
								MainManager.instance.samiramusics.Insert(missing[i], item);
