								MainManager.instance.flags[658] = true;
							}
							else
							{
								MainManager.instance.StartCoroutine(MainManager.SetText("|showmoney|" + MainManager.commondialogue[38], true, Vector3.zero, call.transform, call));
							}
						}
						else
						{
							if (MainManager.listvar.Contains(-1))
							{
								MainManager.listoption--;
							}
							int[] array = new int[2]
							{
								MainManager.instance.samiramusics[MainManager.listoption][0],
								1
							};
							MainManager.instance.samiramusics.RemoveAt(MainManager.listoption);
							MainManager.instance.samiramusics.Insert(MainManager.listoption, array);
							if (!MainManager.instance.flags[658] && MainManager.SamiraGotAll())
							{
								MainManager.instance.StartCoroutine(MainManager.SetText("|showmoney|" + MainManager.commondialogue[183] + "|break||giveitem,1," + 83 + ",-11|", true, Vector3.zero, call.transform, call));
								MainManager.instance.flags[658] = true;
