							else
							{
								MainManager.instance.StartCoroutine(MainManager.SetText("|showmoney|" + MainManager.commondialogue[39], true, Vector3.zero, call.transform, call));
							}
							play = array[0];
						}
					}
					else
					{
						MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.commondialogue[41], true, Vector3.zero, call.transform, call));
					}
					while (MainManager.instance.message)
					{
						yield return null;
					}
				}
				else if (MainManager.instance.option == 1)
				{
					SamiraStop();
				}
			}
			else
			{
				MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.commondialogue[39], true, Vector3.zero, call.transform, call));
				while (MainManager.instance.message)
				{
					yield return null;
				}
				play = MainManager.instance.samiramusics[MainManager.listoption + (MainManager.listvar.Contains(-1) ? (-1) : 0)][0];
			}
		}
		if (play >= 0)
		{
			AudioClip tclip = MainManager.music[0].clip;
			call.entity.animstate = 102;
			MainManager.Musics musics = (MainManager.Musics)play;
			ResourceRequest r = Resources.LoadAsync<AudioClip>("Audio/Music/" + musics);
			while (!r.isDone)
			{
				yield return null;
			}
			MainManager.ChangeMusic((AudioClip)r.asset);
			yield return null;
			if (tclip != null && tclip != MainManager.map.music[0])
			{
				Resources.UnloadAsset(tclip);
			}
			call.internaltransform = new Transform[1];
			call.internaltransform[0] = (UnityEngine.Object.Instantiate(Resources.Load("Prefabs/Particles/MusicSimple")) as GameObject).transform;
			call.internaltransform[0].parent = call.transform;
			call.internaltransform[0].localPosition = new Vector3(0f, 2f, -0.1f);
