			while (MainManager.musiccoroutine != null && failsafe > 0f)
			{
				failsafe -= MainManager.framestep;
				yield return null;
			}
		}
		else
		{
			call.entity.overrideanim = false;
		}
		call.entity.npcdata.dialogues[call.entity.npcdata.currentdialogueindex].z = call.entity.animstate;
		yield return null;
		EndEvent();
	}

