	private IEnumerator EndTheater(bool completed, GameObject[] destroylist, GameObject[] disable, GameObject[] enable)
	{
		RefreshEntities();
		for (int i = 0; i < destroylist.Length; i++)
		{
			UnityEngine.Object.Destroy(destroylist[i]);
		}
		for (int j = 0; j < enable.Length; j++)
		{
			enable[j].SetActive(true);
		}
		for (int k = 0; k < disable.Length; k++)
		{
			disable[k].SetActive(false);
		}
		GameObject.Find("CurtainL").transform.GetChild(0).GetChild(0).localScale = new Vector3(1f, 0f, 1f);
		GameObject.Find("CurtainR").transform.GetChild(0).GetChild(0).localScale = new Vector3(1f, 0f, 1f);
		EntityControl m = MainManager.GetEntity(4);
		m.flip = true;
		for (int l = 0; l < MainManager.map.entities.Length; l++)
		{
			MainManager.map.entities[l].transform.position = MainManager.map.entities[l].startpos.Value;
			MainManager.map.entities[l].animstate = MainManager.map.entities[l].basestate;
		}
		for (int n = 0; n < MainManager.instance.playerdata.Length; n++)
		{
			MainManager.instance.playerdata[n].entity.transform.position = m.transform.position + new Vector3(((n == 0) ? 2.5f : 2f) * (float)(n + 1), 0f, 0f);
			MainManager.instance.playerdata[n].entity.flip = false;
			MainManager.instance.playerdata[n].entity.animstate = 0;
		}
		MainManager.ResetCamera(true);
		if (!completed)
		{
			MainManager.instance.camspeed = 1f;
			MainManager.instance.camtarget = null;
			MainManager.instance.camtargetpos = new Vector3(-6f, 3f, 8.5f);
			MainManager.PlaySound("CrowdGasp");
			MainManager.sounds[14].volume = 1.5f * MainManager.soundvolume;
			MainManager.sounds[14].pitch = 1.2f;
			for (int num = 0; num < MainManager.instance.playerdata.Length; num++)
			{
				MainManager.instance.playerdata[num].entity.animstate = 17;
			}
			m.animstate = 5;
			MainManager.instance.transitionobj[0].GetComponent<SpriteRenderer>().sortingOrder = -10;
			MiniBubble[] mb = new MiniBubble[6];
			for (int num2 = 0; num2 < mb.Length; num2++)
			{
				EntityControl tempent = MainManager.GetEntity((num2 < 3) ? num2 : (num2 - 3));
				tempent.transform.position = new Vector3(UnityEngine.Random.Range(-12.5f, 0.5f), tempent.transform.position.y, tempent.transform.position.z);
				mb[num2] = MiniBubble.SetUp(MainManager.map.dialogues[51 + num2], tempent, MainManager.GetMinibubblePos(tempent.transform, (num2 < 3) ? (-0.5f) : (-0.2f)), -5 + num2 * 3);
				yield return quartersec;
				mb[num2].target = null;
				tempent.talking = false;
			}
			yield return sec;
			MainManager.StopSound(14);
			MainManager.instance.StartCoroutine(MainManager.SetText("|boxstyle,1||size,1.25||quarterline|" + MainManager.map.dialogues[57] + "|fwait,0.25|", true, Vector3.zero, m.transform, null));
			while (MainManager.instance.message)
			{
				yield return null;
			}
			while (mb[mb.Length - 1] != null)
			{
				yield return null;
			}
			yield return sec;
			for (int num3 = 0; num3 < 3; num3++)
			{
				EntityControl entity = MainManager.GetEntity(num3);
				entity.transform.position = entity.startpos.Value;
			}
			MainManager.ResetCamera(true);
			yield return null;
			MainManager.PlayTransition(1, 0, 0.02f, Color.black);
			yield return new WaitForSeconds(0.75f);
			MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.map.dialogues[58], true, Vector3.zero, m.transform, m.npcdata));
			while (MainManager.instance.message)
			{
				yield return null;
			}
		}
		else
		{
			MainManager.StopSound(14);
			yield return null;
			MainManager.PlayTransition(1, 0, 0.02f, Color.black);
			yield return new WaitForSeconds(0.75f);
			MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.map.dialogues[63], true, Vector3.zero, m.transform, m.npcdata));
			while (MainManager.instance.message)
			{
				yield return null;
			}
			if (!MainManager.instance.flags[49])
			{
				MainManager.CompleteQuest(3);
				MainManager.instance.flags[49] = true;
			}
		}
		MainManager.ChangeMusic("Theater");
		yield return null;
		Resources.UnloadUnusedAssets();
		yield return null;
		EndEvent();
	}

