	public static IEnumerator PartyMover(bool jump)
	{
		EntityControl[] t = MainManager.GetPartyEntities(true);
		EntityControl[] h = MainManager.map.tempfollowers.ToArray();
		Vector3 vector = MainManager.instance.globalcamdir.forward.normalized * 0.1f;
		for (int i = 0; i < t.Length; i++)
		{
			if (t[i].transform != MainManager.player.transform)
			{
				t[i].MoveTowards(MainManager.player.transform.position + vector * (i + 1));
				t[i].DetectDirection(t[i].forcetarget);
				t[i].LockRigid(false);
				if (jump)
				{
					t[i].forcejump = true;
				}
			}
		}
		for (int j = 0; j < h.Length; j++)
		{
			if (h[j] != null && !h[j].iskill)
			{
				h[j].MoveTowards(MainManager.player.transform.position + vector * (j + MainManager.instance.playerdata.Length));
				h[j].DetectDirection(h[j].forcetarget);
				h[j].LockRigid(false);
				if (jump)
				{
					h[j].forcejump = true;
				}
			}
		}
		while (!MainManager.PartyIsNotMoving() || !MainManager.EntitiesAreNotMoving(h))
		{
			yield return null;
		}
		for (int k = 0; k < t.Length; k++)
		{
			t[k].forcejump = false;
		}
		for (int l = 0; l < h.Length; l++)
		{
			h[l].forcejump = false;
		}
		temproutine = null;
	}

