					call.entity.animstate = 105;
					sp = rock.transform.position;
					a = 0f;
					call.entity.PlaySound("Pickax3", 1f, 1.15f);
					call.entity.sound.loop = true;
					yield return new WaitForSeconds(0.2f);
					do
					{
						rock.transform.position = sp + MainManager.RandomVector(0.1f);
						a += MainManager.TieFramerate(1f);
						yield return null;
					}
					while (a < 100f);
					MainManager.PlayTransition(4, 0, 0.1f, Color.black);
					yield return null;
					SpriteRenderer t = MainManager.GetTransitionSprite();
					while (t.material.color.a < 0.95f)
					{
						rock.transform.position = sp + MainManager.RandomVector(0.1f);
						call.entity.sound.volume -= MainManager.TieFramerate(0.02f);
						yield return null;
					}
					yield return new WaitForSeconds(0.2f);
					MainManager.instance.flags[flagtoopen] = true;
					sp = call.entity.startpos.Value;
					Vector3[] ppos = new Vector3[3]
					{
						MainManager.GetEntity(-4).transform.position,
						MainManager.GetEntity(-5).transform.position,
						MainManager.GetEntity(-6).transform.position
					};
					MainManager.LoadMap((int)MainManager.map.mapid, true);
					yield return null;
					for (int i = 0; i < MainManager.instance.playerdata.Length; i++)
					{
						MainManager.instance.playerdata[i].entity.transform.position = ppos[i];
						MainManager.instance.playerdata[i].entity.FaceTowards(sp);
					}
					EntityControl tdi = EntityControl.CreateNewEntity("diana", 104, sp);
					tdi.FaceTowards(MainManager.instance.playerdata[0].entity.transform.position);
					MainManager.ResetCamera(true);
					MainManager.instance.camtarget = tdi.transform;
					yield return null;
					yield return new WaitForSeconds(0.75f);
					MainManager.PlayTransition(1, 0, 0.05f, Color.black);
					yield return null;
					t = MainManager.GetTransitionSprite();
					while (t.color.a > 0.05f)
					{
						yield return null;
					}
					MainManager.instance.StartCoroutine(MainManager.SetText(MainManager.commondialogue[72], true, Vector3.zero, tdi.transform, null));
					while (MainManager.instance.message)
					{
