					}
					yield return halfsec;
					MainManager.ResetCamera(true);
					UnityEngine.Object.Destroy(tdi.gameObject);
					yield return new WaitForSeconds(0.75f);
					MainManager.PlayTransition(1, 0, 0.04f, Color.black);
					yield return null;
					t = MainManager.GetTransitionSprite();
					while (t.color.a > 0.05f)
					{
						yield return null;
					}
					MainManager.instance.flagvar[16]++;
				}
			}
		}
		yield return null;
		EndEvent();
	}

