	private IEnumerator Event50()
	{
		if (MainManager.map.mapid == MainManager.Maps.GoldenHillsDungeonUpperMain)
		{
			yield return new WaitForSecondsRealtime(0.25f);
			MainManager.SetCamera(null, new Vector3(12f, 5f, 10f), 0.05f);
			yield return new WaitForSeconds(0.85f);
			Transform gate = GameObject.Find("Gate4").transform;
			float a = 0f;
			float b = 60f;
			MainManager.ShakeScreen(Vector3.one * 0.05f, -1f);
			Vector3[] gsp = new Vector3[gate.childCount];
			for (int i = 0; i < gate.childCount; i++)
			{
				gsp[i] = gate.GetChild(i).position;
			}
			MainManager.PlaySound("Rumble3");
			do
			{
				for (int j = 0; j < gate.childCount; j++)
				{
					Transform child = gate.GetChild(j);
					child.Rotate(0f, 0f, MainManager.TieFramerate(10f));
					child.position = Vector3.Lerp(gsp[j], gsp[j] + new Vector3((j < gate.childCount / 2) ? (-1f) : (-0.15f), -5f, 0f), a / b);
				}
				a += MainManager.TieFramerate(1f);
				yield return null;
			}
			while (a < b);
			MainManager.screenshake = Vector3.zero;
			yield return halfsec;
			UnityEngine.Object.Destroy(gate.gameObject);
			MainManager.ResetCamera();
			MainManager.instance.flags[127] = true;
		}
		else
		{
			bool windmill = MainManager.map.mapid == MainManager.Maps.GoldenSettlement2 || MainManager.map.mapid == MainManager.Maps.GoldenSettlement2Night;
			GameObject gameObject = GameObject.Find(windmill ? "WindmillGate" : "DesertGate");
			Transform[] t = new Transform[2]
			{
				gameObject.transform.GetChild(0),
				gameObject.transform.GetChild(1)
			};
			float[] an = new float[t.Length];
			for (int k = 0; k < an.Length; k++)
			{
				an[k] = t[k].transform.localEulerAngles.z;
			}
			yield return new WaitForSeconds(0.85f);
			if (windmill)
			{
				MainManager.instance.camtarget = null;
				MainManager.instance.camtargetpos = t[0].transform.position + new Vector3(1.5f, 0f);
			}
			float b = 0f;
			do
			{
				for (int l = 0; l < t.Length; l++)
				{
					t[l].transform.localEulerAngles = new Vector3(0f, 0f, an[l] + Mathf.Sin(Time.time * 15f) * 3f * MainManager.TieFramerate((l == 0) ? 1 : (-1)));
				}
				b += MainManager.TieFramerate(1f);
				yield return null;
			}
			while (b < 60f);
			yield return halfsec;
			b = 0f;
			MainManager.PlaySound("Creak");
			do
			{
				for (int m = 0; m < t.Length; m++)
				{
					t[m].transform.localEulerAngles = new Vector3(0f, 0f, Mathf.LerpAngle(an[m], (m == 0) ? 100 : 80, b / 40f));
				}
				b += MainManager.TieFramerate(1f);
				yield return null;
			}
			while (b < 40f);
			yield return new WaitForSeconds(0.3f);
			MainManager.instance.flags[windmill ? 90 : 83] = true;
			if (windmill)
			{
				MainManager.ResetCamera();
			}
		}
		yield return null;
		EndEvent();
	}

