	private static bool HasEnoughCards()
	{
		string[] array = Resources.Load<TextAsset>("Data/CardData").ToString().Split('\n');
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		for (int i = 0; i < array.Length; i++)
		{
			string[] array2 = array[i].Split(',');
			int num4 = Convert.ToInt32(array2[2]);
			if (MainManager.instance.librarystuff[1, num4])
			{
				switch ((CardGame.Type)Convert.ToInt32(array2[4]))
				{
				case CardGame.Type.Boss:
					num++;
					break;
				case CardGame.Type.Miniboss:
					num2++;
					break;
				default:
					num3++;
					break;
				}
			}
		}
		if (num > 0 && num2 > 1)
		{
			return num3 > 0;
		}
		return false;
	}

