	private IEnumerator Event94()
	{
		MainManager.map.StopMovingEntities();
		Transform transform = null;
		bool water = call.name.Contains("WTA");
		if (water)
		{
			call.name = call.name.Replace("WTA", "");
		}
		float yvar = 0f;
		for (int i = 0; i < call.name.Length; i++)
		{
			if (call.name[i] == '|')
			{
				string text = "";
				for (int j = i + 1; j < call.name.Length; j++)
				{
					text += call.name[j];
				}
				yvar = Convert.ToSingle(text);
				call.name = call.name.Replace("|" + text, "");
			}
		}
		if (call.name[0] != '@')
		{
			transform = ((MainManager.map.mapid != MainManager.Maps.DesertTrenchSouth) ? MainManager.map.transform.GetChild(0).GetChild(call.mapid - 2) : MainManager.map.transform.GetChild(0).GetChild(0));
		}
		else
		{
			call.name = call.name.Replace("@", "");
			for (int k = 0; k < MainManager.map.mainmesh.childCount; k++)
			{
				if (MainManager.map.mainmesh.GetChild(k).name == call.name)
				{
					transform = MainManager.map.mainmesh.GetChild(k);
					break;
				}
			}
		}
		Transform[] s = new Transform[2]
		{
			transform.GetChild(0),
			transform.GetChild(2)
		};
		ConditionChecker c = s[1].GetComponent<ConditionChecker>();
		float a = 0f;
		float b = 200f;
		MainManager.PlaySound("Damage0");
		MainManager.PlaySound("Creak2");
		Vector3 an = s[0].eulerAngles;
		Vector3 p = transform.position + transform.forward * 10f + transform.up * 2f;
		Vector3 ppp = s[0].position;
		Vector3 vector = transform.position + new Vector3(0f, yvar);
		GameObject pp = UnityEngine.Object.Instantiate(Resources.Load("Prefabs/Particles/ContinuousSmokeSphere"), transform.position + new Vector3(0f, 0.5f), Quaternion.identity) as GameObject;
		pp.transform.localScale = Vector3.one * 0.3f;
		MainManager.SetCamera(null, p, 0.015f);
		Vector3 tp = (water ? new Vector3(c.startpos.x, Mathf.Clamp(MainManager.map.waterfloat.transform.position.y, MainManager.map.waterfloat.minwaterfloat, float.PositiveInfinity), c.startpos.z) : c.startpos);
		do
		{
			s[0].transform.position = Vector3.Lerp(ppp, tp, a / b);
			s[0].eulerAngles = MainManager.LerpVectorAngle(an, c.startangle, a / b);
			a += MainManager.TieFramerate(1f + a / b * 5f);
			yield return null;
		}
		while (a < b + 1f);
		s[0].eulerAngles = c.startangle;
		s[0].position = tp;
		pp.transform.position = new Vector3(0f, -9999f);
		UnityEngine.Object.Destroy(pp.gameObject, 3f);
		if (water && s[0].transform.position.y > MainManager.map.waterfloat.minwaterfloat)
		{
			pp = UnityEngine.Object.Instantiate(Resources.Load<GameObject>("Prefabs/Objects/WaterSplash"), Vector3.Lerp(p, call.entity.startpos.Value, 0.45f) + new Vector3(0f, yvar), Quaternion.identity);
			pp.transform.localScale = Vector3.one * 2f;
			UnityEngine.Object.Destroy(pp, 0.75f);
		}
		else
		{
			if (MainManager.map.mapid == MainManager.Maps.DesertSandPitArea)
			{
				p += s[0].transform.forward * 1.75f;
			}
			MainManager.PlayParticle("impactsmoke", p + new Vector3(0f, yvar));
			MainManager.ShakeScreen(0.3f, 0.75f);
			MainManager.instance.camtargetpos = null;
			MainManager.PlaySound("Thud3");
		}
		MeshCollider m = s[0].GetComponentInChildren<MeshCollider>();
		m.enabled = false;
		yield return sec;
		m.enabled = true;
		if (MainManager.map.mapid == MainManager.Maps.DesertSandPitArea)
		{
			MainManager.instance.flags[200 + call.mapid] = true;
		}
		else
		{
			MainManager.instance.flags[call.activationflag] = true;
		}
		MainManager.ResetCamera();
		yield return null;
		EndEvent();
	}

