				MainManager.instance.items[1].Remove(100);
				num = 101;
				commonid = 102;
			}
			else if (MainManager.instance.items[1].Contains(101))
			{
				MainManager.instance.items[1].Remove(101);
				num = 102;
				commonid = 103;
			}
			else if (MainManager.instance.items[1].Contains(102))
			{
				MainManager.instance.items[1].Remove(102);
				num = 103;
				commonid = 104;
			}
			else if (MainManager.instance.items[1].Contains(103))
			{
				MainManager.instance.items[1].Remove(103);
				num = 104;
				MainManager.instance.flags[245] = true;
				commonid = 105;
			}
			switch (MainManager.map.mapid)
			{
			case MainManager.Maps.DefiantRoot3:
				redirectid = ((commonid == 105) ? 112 : 111);
				MainManager.instance.flags[233] = true;
				break;
			case MainManager.Maps.HBsLab:
