			case MainManager.Maps.GoldenSettlement3:
				redirectid = ((commonid == 105) ? 21 : 20);
				MainManager.instance.flags[235] = true;
				break;
			}
			MainManager.instance.StartCoroutine(MainManager.SetText("|giveitem,1," + num + ",-11|", true, Vector3.zero, call.transform, call));
