		entity.overrridejump = true;
		entity.animstate = 109;
		MainManager.PlaySound("Buzz1");
		SpriteRenderer[] ts = new SpriteRenderer[2];
		for (int i = 0; i < ts.Length; i++)
		{
			ts[i] = new GameObject("tsprite").AddComponent<SpriteRenderer>();
			ts[i].sprite = entity.sprite.sprite;
			ts[i].color = new Color(1f, 1f, 1f, 0.35f);
			ts[i].transform.position = entity.transform.position;
			ts[i].flipX = true;
		}
		float a = 0f;
		while (a < 30f)
		{
			if (Mathf.FloorToInt(a) % 3 == 0)
			{
				entity.sprite.enabled = !entity.sprite.enabled;
				for (int j = 0; j < ts.Length; j++)
				{
					ts[j].enabled = !entity.sprite.enabled;
					if (ts[j].enabled)
					{
						ts[j].transform.position = entity.transform.position + new Vector3(UnityEngine.Random.Range(-1.25f, 1.25f) * (a / 30f), 0f);
					}
				}
			}
			a += MainManager.TieFramerate(1f);
			yield return null;
		}
		for (int k = 0; k < ts.Length; k++)
		{
			UnityEngine.Object.Destroy(ts[k].gameObject);
		}
		entity.sprite.enabled = true;
		yield return new WaitForSeconds(0.15f);
		entity.animstate = poststate;
		entity.LockRigid(lockrigid);
		entity.overrridejump = false;
		entity.overrideanim = false;
		temproutine = null;
	}

