	private IEnumerator Event134()
	{
		bool follow = false;
		if (!MainManager.instance.flags[402] && ((MainManager.map.mapid == MainManager.Maps.BugariaMainPlaza && !MainManager.instance.flags[403]) || (MainManager.map.mapid == MainManager.Maps.HoneycombsLab && !MainManager.instance.flags[405])))
