		}
		else if (MainManager.instance.flags[402])
		{
			MainManager.instance.StartCoroutine(MainManager.SetText("|boxstyle,4||spd,0|" + MainManager.commondialogue[136] + "|prompt,yesno,-11,-11|", true, Vector3.zero, null, null));
			while (MainManager.instance.message)
			{
				yield return null;
			}
			if (MainManager.instance.option == 0)
			{
				follow = true;
			}
		}
		else
		{
			List<int> ribbons = new List<int>(ChompyRibbons());
			if (ribbons.Count == 0 && !MainManager.instance.flags[404])
			{
				MainManager.instance.StartCoroutine(MainManager.SetText("|boxstyle,4||spd,0|" + MainManager.commondialogue[130] + "|prompt,yesno,-11,-11|", true, Vector3.zero, null, null));
				while (MainManager.instance.message)
				{
					yield return null;
				}
				if (MainManager.instance.option == 0)
				{
					follow = true;
				}
			}
			else
			{
				MainManager.instance.StartCoroutine(MainManager.SetText("|boxstyle,4||spd,0|" + MainManager.commondialogue[131] + "|prompt,map,2,3,-11,-11,-11,-135," + (MainManager.instance.flags[404] ? (-134) : (-133)) + ",-136|", true, Vector3.zero, null, null));
				while (MainManager.instance.message)
				{
					yield return null;
				}
				switch (MainManager.instance.option)
				{
				case 0:
					follow = true;
					break;
				case 1:
				{
					if (MainManager.instance.flags[404])
					{
						if (MainManager.instance.flagvar[56] == 0)
						{
							MainManager.instance.items[1].Add(94);
						}
						else
						{
							MainManager.instance.items[1].Add(MainManager.instance.flagvar[56]);
						}
						MainManager.instance.flags[404] = false;
						break;
					}
					if (ribbons.Count > 1)
					{
						string text = ribbons.Count + ",";
						for (int i = 0; i < ribbons.Count; i++)
						{
							text += "-11,";
						}
						for (int j = 0; j < ribbons.Count; j++)
						{
							text = text + "@" + MainManager.itemdata[0, ribbons[j], 0] + ",";
						}
						MainManager.instance.StartCoroutine(MainManager.SetText("|boxstyle,4||spd,0|" + MainManager.commondialogue[174] + "|prompt,map,0," + text + "none|", true, Vector3.zero, null, null));
						while (MainManager.instance.message)
						{
							yield return null;
						}
					}
					else
					{
						MainManager.instance.option = 0;
					}
					int num = ribbons[MainManager.instance.option];
					MainManager.instance.items[1].Remove(num);
					MainManager.instance.flagvar[56] = num;
					MainManager.instance.flags[404] = true;
					break;
				}
				}
			}
		}
		if (follow)
		{
			MainManager.instance.flags[402] = !MainManager.instance.flags[402];
			if (!MainManager.instance.flags[402])
			{
				MainManager.instance.flags[403] = MainManager.map.mapid == MainManager.Maps.BugariaMainPlaza;
				MainManager.instance.flags[405] = MainManager.map.mapid == MainManager.Maps.HoneycombsLab;
			}
			else
			{
				MainManager.instance.flags[403] = false;
				MainManager.instance.flags[405] = false;
			}
			MainManager.FadeIn();
			yield return new WaitForSeconds(0.75f);
			MainManager.LoadMap();
			yield return halfsec;
			if (MainManager.map.mapid == MainManager.Maps.BugariaMainPlaza)
			{
				ChangeInside(1, MainManager.GetEntity(4).npcdata);
			}
			MainManager.FadeOut();
			yield return halfsec;
		}
		yield return null;
		EndEvent();
	}

	private void ChangeInside(int insideid, NPCControl door)
	{
		int insideid2 = MainManager.instance.insideid;
		MainManager.instance.insideid = insideid;
		MainManager.map.SetTCLimits(door);
		MainManager.map.RefreshInsides(true, door);
		if (insideid > -1)
		{
			Animator component = MainManager.map.insides[insideid].GetComponent<Animator>();
			if (component != null)
			{
				component.Play("StayOpen");
			}
			Renderer[] componentsInChildren = MainManager.map.insides[insideid].GetComponentsInChildren<Renderer>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				componentsInChildren[i].enabled = true;
			}
			for (int j = 0; j < MainManager.map.insides.Length; j++)
			{
				MainManager.map.insides[j].SetActive(insideid == j);
			}
		}
		else
		{
			Animator component2 = MainManager.map.insides[insideid2].GetComponent<Animator>();
			if (component2 != null)
			{
				component2.Play("StayClose");
			}
			MainManager.map.RefreshInsides(false, door);
		}
		MainManager.map.HideRenders();
	}

