	private void MoveParty(Vector3[] pos, bool order)
	{
		MoveParty(pos, order, 1f);
	}

	private void MoveParty(Vector3[] pos, bool order, float speedmult)
	{
		EntityControl[] partyEntities = MainManager.GetPartyEntities(order);
		for (int i = 0; i < partyEntities.Length; i++)
		{
			partyEntities[i].MoveTowards(pos[i], speedmult);
		}
		MoveChompy(pos[pos.Length - 1]);
	}

	private void MoveParty(Vector3[] pos)
	{
		MoveParty(pos, false);
	}

