	private IEnumerator SlideDoorOpen(Transform doorparent, bool open, float multiplier, bool destroy)
	{
		Transform[] door = new Transform[2]
		{
			doorparent.GetChild(0),
			doorparent.GetChild(1)
		};
		Vector3[] array = new Vector3[2]
		{
			door[0].localPosition,
			door[1].localPosition
		};
		MainManager.PlaySound(open ? "Door2" : "Door3", -1, 1.1f, 1f);
		float num = (open ? 6f : 0.45f);
		for (int i = 0; i < door.Length; i++)
		{
			door[i].gameObject.isStatic = false;
			StartCoroutine(MainManager.MoveTowards(door[i], new Vector3((i == 0) ? (0f - num) : num, array[i].y, array[i].z), 40f * multiplier, true, true));
		}
		yield return new WaitForSeconds(0.75f * multiplier);
		if (destroy)
		{
			for (int j = 0; j < door.Length; j++)
			{
				UnityEngine.Object.Destroy(door[j].gameObject);
			}
		}
		temproutine = null;
	}

