						{
							yield return null;
						}
						break;
					}
					temproutine = StartCoroutine(PartyMover(false));
					call.entity.LockRigid(true);
					call.entity.ForceMove(callpos, 30f, false);
					call.entity.ccol.enabled = true;
					float b = 60f;
					while (b > 0f && (temproutine != null || call.entity.forcemoving != null))
					{
						b -= MainManager.framestep;
						yield return null;
					}
					if (temproutine != null)
					{
						StopCoroutine(temproutine);
					}
					MainManager.battlelossevent = false;
					MainManager.ResetCamera();
					MainManager.ChangeMusic();
					MainManager.instance.flags[162] = false;
					MainManager.InventoryFromString(it, 0, false);
				}
			}
		}
		yield return null;
		EndEvent();
	}

