	private IEnumerator ColiseumEnd(bool win)
	{
		MainManager.StopSound("CrowdChatter");
		if (!win)
		{
			MainManager.PlaySound("CrowdGasp");
			yield return sec;
			MainManager.GetTransitionSprite().sortingOrder = -20;
			MainManager.instance.StartCoroutine(MainManager.SetText("|bleep,0||boxstyle,1|" + MainManager.map.dialogues[51], true, Vector3.zero, null, null));
			while (MainManager.instance.message)
			{
				yield return null;
			}
			yield return sec;
		}
		MainManager.LoadMap(178);
		yield return null;
		MainManager.ChangeMusic();
		EntityControl recep = MainManager.GetEntity(2);
		SetPartyPos(new Vector3[4]
		{
			new Vector3(0f, 0f, 2f),
			new Vector3(-2.45f, 0f, 2f),
			new Vector3(2f, 0f, 2f),
			new Vector3(-4.2f, 0f, 2f)
		});
		for (int i = 0; i < MainManager.instance.playerdata.Length; i++)
		{
			MainManager.instance.playerdata[i].entity.animstate = 0;
