	private void SetPartyPos(Vector3 pos)
	{
		SetPartyPos(new Vector3[4] { pos, pos, pos, pos }, null, null);
	}

	private void SetPartyPos(Vector3[] pos, int[] anims)
	{
		SetPartyPos(pos, null, anims);
	}

	private void SetPartyPos(Vector3[] pos)
	{
		SetPartyPos(pos, (bool[])null);
	}

	private void SetPartyPos(Vector3[] pos, bool[] flips)
	{
		SetPartyPos(pos, flips, new int[4]);
	}

	private void SetPartyPos(Vector3[] pos, bool[] flips, int[] anims)
	{
		EntityControl[] partyEntities = MainManager.GetPartyEntities(true);
		for (int i = 0; i < partyEntities.Length; i++)
		{
			partyEntities[i].transform.position = pos[i];
			if (flips != null)
			{
				partyEntities[i].flip = flips[i];
			}
			if (anims != null)
			{
				partyEntities[i].animstate = anims[i];
			}
		}
		if (Chompy() != null)
		{
			Chompy().transform.position = pos[pos.Length - 1];
			if (flips != null)
			{
				Chompy().flip = flips[flips.Length - 1];
			}
			if (anims != null)
			{
				Chompy().animstate = anims[anims.Length - 1];
			}
		}
	}

