	private IEnumerator ShakeJump(bool flipafter)
	{
		EntityControl[] p = MainManager.GetPartyEntities(true);
		for (int i = 0; i < p.Length; i++)
		{
			StartCoroutine(p[i].ShakeSprite(new Vector3(0.1f, 0f), 60f));
			yield return sec;
			MainManager.PlaySound("Jump");
			p[i].Jump();
		}
		if (Chompy() != null)
		{
			yield return halfsec;
			MainManager.PlaySound("Jump", -1, 1.25f, 1f);
			Chompy().Jump();
		}
		if (flipafter)
		{
			yield return halfsec;
			for (int i = 0; i < 3; i++)
			{
				for (int j = 0; j < p.Length; j++)
				{
					p[j].FlipSimple();
				}
				yield return halfsec;
			}
		}
		temproutine = null;
	}

