			SpriteRenderer s = MainManager.NewSpriteObject(Vector3.Lerp(t, MainManager.player.transform.position, 0.5f) + new Vector3(0f, 0.5f), null, MainManager.itemsprites[0, MainManager.instance.flagvar[1]]);
