			MainManager.instance.items[0].Remove(MainManager.instance.flagvar[1]);
			sp.overrideanim = true;
			sp.overrridejump = true;
			sp.animstate = 101;
			do
			{
				sp.transform.position = Vector3.Lerp(sp.startpos.Value, t, a / b);
				a += MainManager.TieFramerate(1f);
				yield return null;
			}
			while (a < b + 1f);
			sp.animstate = 100;
			yield return new WaitForSeconds(0.75f);
			a = 0f;
			b = 30f;
			sp.animstate = 101;
			do
			{
				sp.transform.position = Vector3.Lerp(t, new Vector3(s.transform.position.x - 1f, 2f, s.transform.position.z), a / b);
				a += MainManager.TieFramerate(1f);
				yield return null;
			}
			while (a < b + 1f);
			sp.animstate = 100;
			yield return halfsec;
			UnityEngine.Object.Destroy(s.gameObject);
			yield return halfsec;
			sp.animstate = 101;
			a = 0f;
			b = 60f;
			t = sp.transform.position;
			do
			{
				sp.transform.position = Vector3.Lerp(t, sp.startpos.Value, a / b);
				a += MainManager.TieFramerate(1f);
				yield return null;
			}
			while (a < b + 1f);
			yield return halfsec;
			int money = Convert.ToInt32(MainManager.itemdata[0, MainManager.instance.flagvar[1], 4]);
			MainManager.Items items = (MainManager.Items)MainManager.instance.flagvar[1];
			if (items == MainManager.Items.TangyBerry || items == MainManager.Items.BlackCherry)
			{
				money /= 2;
			}
			for (int i = 0; i < money; i++)
			{
				if (!MainManager.instance.crystalbflags[38] && !MainManager.map.mapflags[0])
				{
					EntityControl.CreateItem(new Vector3(-16f, 2f, 3.5f), 3, 38, new Vector3(5f * UnityEngine.Random.Range(1f, 1.25f), 10f, UnityEngine.Random.Range(-2.5f, 2.5f)), -1);
					MainManager.map.mapflags[0] = true;
				}
				EntityControl.CreateItem(new Vector3(-16f, 2f, 3.5f), 0, (money - i > 20) ? 186 : ((money - i > 5) ? 7 : 6), new Vector3(5f * UnityEngine.Random.Range(1f, 1.5f), 10f, UnityEngine.Random.Range(-2.5f, 2.5f)), 300);
				if (money - i > 20)
				{
					i += 19;
				}
				else if (money - i > 5)
				{
					i += 4;
				}
				yield return null;
				yield return null;
			}
			MainManager.instance.flags[451] = true;
			yield return new WaitForSeconds(0.75f);
			MainManager.ResetCamera();
		}
		yield return null;
		EndEvent();
	}

