			MainManager.SetCamera(new Vector3(-56.45f, 0.85f, -0.55f), new Vector3(10f, -45f), 0.035f);
			door = MainManager.map.mainmesh.GetChild(0);
			doordir = -8f;
			break;
		case MainManager.Maps.UpperSnekSwitchPuzzle:
			MainManager.SetCamera(new Vector3(-25.7f, 0f, 1f), new Vector3(10f, -30f), 0.035f);
			door = MainManager.map.mainmesh.GetChild(0);
			spin = -1f;
			doordir = 8f;
			break;
		case MainManager.Maps.UpperSnekMiddleRoom:
			MainManager.PlaySound("Slot3");
			keeplimits = true;
			if (call.mapid == 6)
			{
				door = MainManager.map.mainmesh.GetChild(1);
				doordir = -8f;
			}
			else
			{
				door = MainManager.map.mainmesh.GetChild(0);
				doordir = 8f;
				spin = -1f;
			}
			UnityEngine.Object.Destroy(call.gameObject);
			break;
		}
		yield return sec;
		MainManager.ShakeScreen(0.1f, -1f);
		MainManager.PlaySound("Rumble", -1, 1f, 1f, true);
		Vector3[] ml = (keeplimits ? null : SaveMapLimits(true));
		yield return halfsec;
		float a = 0f;
		float b = 200f;
		Vector3 s = door.transform.position;
		Vector3 p = door.transform.position + door.transform.right.normalized * doordir;
		do
		{
			float num = MainManager.TieFramerate(1f);
			door.transform.position = Vector3.Lerp(s, p, a / b);
			door.transform.eulerAngles += new Vector3(0f, 0f, -1.25f * num * spin);
			a += num;
			yield return null;
		}
		while (a < b + 1f);
		UnityEngine.Object.Destroy(door.gameObject);
		MainManager.StopSound("Rumble");
		MainManager.PlaySound("ThudRocks");
		MainManager.ShakeScreen(0.2f, 1f);
		yield return sec;
		yield return halfsec;
		MainManager.ResetCamera();
		if (!keeplimits)
		{
			ReturnMapLimits(ml);
		}
		yield return null;
		EndEvent();
	}

