			}
			int[] rewards = new int[10] { -20, 1043, 1044, -25, 69, -30, 1045, 1046, 1047, 2083 };
			bool onereward = false;
			int discamt = 0;
			int r = 0;
			for (int i = 0; i < MainManager.librarylimit[0]; i++)
			{
				if (MainManager.instance.librarystuff[0, i])
				{
					discamt++;
				}
			}
