						{
							MainManager.instance.playerdata[i].entity.animstate = 11;
						}
						yield return halfsec;
						MainManager.PlayParticle("Gleam", "Gleam", call.entity.sprite.transform.position + new Vector3(-2f, 0.9f), new Vector3(-90f, 0f), 0.5f);
						MainManager.PlayTransition(4, 0, 0.075f, Color.black);
						yield return halfsec;
						yield return sec;
					}
					for (int j = 0; j < MainManager.instance.badges.Count; j++)
					{
						MainManager.instance.badges[j][1] = -2;
					}
					List<int[]> list = new List<int[]>();
					for (int k = 0; k < stats.Length; k++)
					{
						switch ((MainManager.StatBonus)stats[k][0])
						{
						case MainManager.StatBonus.HP:
							if (stats[k][2] == -1)
							{
								MainManager.instance.items[1].Add(135);
							}
							else
							{
								MainManager.instance.items[1].Add(131);
							}
							break;
						case MainManager.StatBonus.Attack:
							MainManager.instance.items[1].Add(132);
							break;
						case MainManager.StatBonus.Defense:
							MainManager.instance.items[1].Add(133);
							break;
						case MainManager.StatBonus.MP:
							if (!MainManager.instance.flags[613])
							{
								MainManager.instance.items[1].Add(137);
							}
							else
							{
								list.Add(stats[k]);
							}
							break;
						case MainManager.StatBonus.TP:
							if (stats[k][1] == 3)
							{
								MainManager.instance.items[1].Add(136);
							}
							else
							{
								MainManager.instance.items[1].Add(134);
							}
							break;
						}
					}
					MainManager.instance.statbonus = new List<int[]>();
					if (list.Count > 0)
					{
						MainManager.instance.statbonus.AddRange(list.ToArray());
					}
					MainManager.ApplyStatBonus();
					MainManager.ApplyBadges();
					MainManager.instance.maxbp = (MainManager.instance.flags[613] ? mp : 5);
					MainManager.instance.bp = MainManager.instance.maxbp;
