	private IEnumerator Event201()
	{
		while (MainManager.instance.message)
		{
			yield return null;
		}
		int targetmap = 0;
		int firstmap = (int)MainManager.map.mapid;
		int callid = call.mapid;
		int type = 0;
		int typeafter = 2;
		Transform elobj = null;
		Transform[] extras = null;
		Vector3[] ev = null;
		Vector3 tpos = Vector3.zero;
		Vector3 jumpto = Vector3.zero;
		switch (MainManager.map.mapid)
		{
		case MainManager.Maps.GiantLairFridgeInside:
			targetmap = 237;
			elobj = MainManager.map.mainmesh.GetChild(0);
			tpos = new Vector3(-9.5f, 5f, 41f);
			break;
		case MainManager.Maps.GiantLairRoachVillage:
			if (call.mapid == 4)
			{
				targetmap = 236;
				elobj = MainManager.map.mainmesh.GetChild(0);
				tpos = new Vector3(9.05f, 17.13f, 7.17f);
				break;
			}
			call.entity.flip = false;
			targetmap = 232;
			elobj = MainManager.map.mainmesh.GetChild(1).GetChild(1);
			extras = new Transform[3]
			{
				MainManager.map.mainmesh.GetChild(1).GetChild(4),
				elobj.GetChild(0).GetChild(0),
				MainManager.map.mainmesh.GetChild(1).GetChild(3)
			};
			ev = new Vector3[2]
			{
				extras[1].localScale,
				new Vector3(13.33f, 13.33f, 145f)
			};
			typeafter = 3;
			jumpto = elobj.transform.position + new Vector3(0f, 0.5f);
			tpos = elobj.transform.localPosition + new Vector3(0f, 0f, -15f);
			break;
		case MainManager.Maps.GiantLairEntrance:
			type = 1;
			typeafter = 2;
			targetmap = 237;
			tpos = new Vector3(13.2f, 0f, 23f);
			break;
		}
		for (int e = 0; e < 2; e++)
		{
			switch (type)
			{
			case 0:
			case 2:
			{
				if (type == 0)
				{
					if (jumpto.magnitude > 0.1f)
					{
						MainManager.PlaySound("Jump");
						MainManager.player.jumproutine = StartCoroutine(MainManager.player.JumpTo(jumpto, 5f));
						while (MainManager.player.jumproutine != null)
						{
							yield return null;
						}
					}
					MainManager.PlaySound("WoodStart");
				}
				for (int i = 0; i < MainManager.instance.playerdata.Length; i++)
				{
					MainManager.instance.playerdata[i].entity.transform.parent = elobj;
					MainManager.instance.playerdata[i].entity.LockRigid(true);
					MainManager.instance.playerdata[i].entity.ccol.enabled = false;
				}
				MainManager.player.transform.localPosition = new Vector3(0f, 0f, 0.65f);
				SpinAround s = elobj.GetChild(0).gameObject.AddComponent<SpinAround>();
				s.itself = new Vector3(0f, 7f);
				MainManager.TeleportFollowers(MainManager.TPDir.Center, MainManager.player.transform.position);
				if (MainManager.map.chompy != null)
				{
					MainManager.map.chompy.transform.position = MainManager.player.transform.position + new Vector3(0f, 0f, 0.35f);
					MainManager.map.chompy.transform.parent = elobj;
				}
				MainManager.ResetCamera(true);
				yield return null;
				yield return null;
				Vector3 sp = elobj.localPosition;
				if (type == 0)
				{
					MainManager.ShakeScreen(0.2f, 0.75f);
					yield return sec;
					MainManager.PlaySound("ElevatorStart");
				}
				else
				{
					MainManager.FadeOut();
					MainManager.PlaySound("ElevatorEnd");
					Vector3 localPosition = elobj.localPosition;
					elobj.localPosition = tpos;
					sp = tpos;
					tpos = localPosition;
				}
				MainManager.SetCamera(null, null, 0f);
				float a = 0f;
				float b = 100f;
				bool half = false;
				do
				{
					if (extras != null)
					{
						extras[0].Rotate(new Vector3(0f, 0f, 10f * MainManager.framestep));
						extras[1].Rotate(new Vector3(0f, 0f, 10f * MainManager.framestep));
						extras[2].Rotate(new Vector3(0f, 10f * MainManager.framestep));
						extras[1].localScale = Vector3.Lerp(ev[0], ev[1], (type == 0) ? (a / b) : (1f - a / b));
					}
					elobj.localPosition = Vector3.Lerp(sp, tpos, a / b);
					if (type == 0 && !half && a / b > 0.5f)
					{
						half = true;
						MainManager.FadeIn();
					}
					a += MainManager.framestep;
					yield return null;
				}
				while (a < b + 1f);
				for (int j = 0; j < MainManager.instance.playerdata.Length; j++)
				{
					MainManager.instance.playerdata[j].entity.transform.parent = null;
					MainManager.instance.playerdata[j].entity.LockRigid(false);
					MainManager.instance.playerdata[j].entity.ccol.enabled = true;
				}
				if (type == 0)
				{
					MainManager.LoadMap(targetmap);
					yield return null;
					while (MainManager.map == null || MainManager.map.mainmesh == null)
					{
						yield return null;
					}
				}
				else
				{
					UnityEngine.Object.Destroy(s);
					MainManager.ShakeScreen(0.1f, 0.5f);
					MainManager.PlaySound("WoodEnd");
					yield return sec;
					if (jumpto.magnitude > 0.1f)
					{
						MainManager.ResetCamera();
						MainManager.PlaySound("Jump");
						MainManager.player.jumproutine = StartCoroutine(MainManager.player.JumpTo(jumpto, 5f));
						while (MainManager.player.jumproutine != null)
						{
							yield return null;
						}
					}
				}
				switch (firstmap)
				{
				case 236:
					tpos = new Vector3(9.05f, 17.13f, 7.17f);
					elobj = MainManager.map.mainmesh.GetChild(0);
					break;
				case 237:
					if (callid == 4)
					{
						tpos = new Vector3(-9.5f, 5f, 41f);
						elobj = MainManager.map.mainmesh.GetChild(0);
					}
					else
					{
						tpos = new Vector3(13.2f, 0f, 23f);
						ev = new Vector3[1]
						{
							new Vector3(13.2f, 0f, 17f)
						};
					}
					break;
				}
				break;
			}
			case 1:
			case 3:
				if (type == 3)
				{
					MainManager.player.transform.position = tpos;
					MainManager.TeleportFollowers(MainManager.TPDir.Center, MainManager.player.transform.position);
					if (MainManager.map.chompy != null)
					{
						MainManager.map.chompy.transform.position = MainManager.player.transform.position + new Vector3(0f, 0f, 0.35f);
					}
					MainManager.ResetCamera(true);
					MainManager.PlaySound("WoodEnd");
					MainManager.instance.overridefollower = false;
					tpos = ev[0];
					yield return sec;
					MainManager.FadeOut();
				}
				else
				{
					MainManager.FadeIn();
				}
				MainManager.instance.overridefollower = false;
				MainManager.player.entity.MoveTowards(tpos);
				while (MainManager.player.entity.forcemove)
				{
					yield return null;
				}
				if (type == 1)
				{
					SpriteRenderer d = MainManager.GetTransitionSprite();
					while (d.color.a < 0.975f)
					{
						yield return null;
					}
					yield return halfsec;
					MainManager.PlaySound("ElevatorStart");
					yield return sec;
					MainManager.LoadMap(targetmap);
					yield return null;
					yield return quartersec;
					elobj = MainManager.map.mainmesh.GetChild(1).GetChild(1);
					extras = new Transform[3]
					{
						MainManager.map.mainmesh.GetChild(1).GetChild(4),
						elobj.GetChild(0).GetChild(0),
						MainManager.map.mainmesh.GetChild(1).GetChild(3)
					};
					ev = new Vector3[2]
					{
						extras[1].localScale,
						new Vector3(13.33f, 13.33f, 145f)
					};
					jumpto = new Vector3(-56.35f, 0f, -15.8f);
					tpos = elobj.localPosition + new Vector3(0f, 0f, -15f);
				}
				break;
			}
			type = typeafter;
		}
		MainManager.ResetCamera();
		yield return null;
		EndEvent();
	}

