			{
				MainManager.instance.maxbp = 4;
			}
			MainManager.instance.flagvar[1] = Mathf.FloorToInt((30f + (float)(MainManager.instance.partylevel - 1) * 10f) * (MainManager.instance.flags[656] ? 1.05f : 1f));
			MainManager.DialogueText(MainManager.map.dialogues[71] + "|showmoney||prompt,yesno,-11,72|", call.transform, call);
			while (MainManager.instance.message)
			{
				yield return null;
			}
			if (MainManager.instance.option == 0)
			{
				if (MainManager.instance.money < MainManager.instance.flagvar[1])
				{
					MainManager.DialogueText(MainManager.map.dialogues[131], call.transform, call);
				}
				else
				{
					MainManager.instance.partylevel++;
					MainManager.instance.flagvar[2] = MainManager.instance.partylevel;
					MainManager.DialogueText("|money,-" + MainManager.instance.flagvar[1] + "||showmoney|" + MainManager.map.dialogues[132], call.transform, call);
					while (MainManager.instance.message)
					{
						yield return null;
					}
					MainManager.DialogueText(MainManager.map.dialogues[139], call.transform, call);
					while (MainManager.instance.message)
					{
						yield return null;
					}
					MainManager.instance.bp++;
					MainManager.instance.maxbp++;
					string[] ld = Resources.Load<TextAsset>("Data/LevelData").ToString().Split('\n');
					for (int i = 0; i < ld.Length; i++)
					{
						string[] array = ld[i].Split(',');
						if (Convert.ToInt32(array[0]) != MainManager.instance.partylevel)
						{
							continue;
						}
						switch (Convert.ToInt32(array[1]))
						{
						case 0:
							MainManager.instance.flagstring[0] = MainManager.skilldata[Convert.ToInt32(array[3]), 0];
							MainManager.DialogueText(MainManager.map.dialogues[133], call.transform, call);
							while (MainManager.instance.message)
							{
								yield return null;
							}
							break;
						case 3:
							MainManager.instance.maxitems += Convert.ToInt32(array[2]);
							MainManager.instance.flagstring[0] = string.Concat(MainManager.instance.maxitems);
							MainManager.DialogueText(MainManager.map.dialogues[134], call.transform, call);
							while (MainManager.instance.message)
							{
								yield return null;
							}
							break;
						}
					}
					if (MainManager.instance.partylevel >= 27)
					{
						MainManager.DialogueText(MainManager.map.dialogues[135], call.transform, call);
					}
					else
					{
						MainManager.DialogueText(MainManager.map.dialogues[138], call.transform, call);
					}
				}
				while (MainManager.instance.message)
				{
					yield return null;
				}
			}
		}
		yield return null;
		EndEvent();
	}

	private static EntityControl GetFollower(int id)
	{
		for (int i = 0; i < MainManager.map.tempfollowers.Count; i++)
		{
			if (MainManager.map.tempfollowers[i].animid == id)
			{
				return MainManager.map.tempfollowers[i];
			}
		}
		return null;
	}

