					MainManager.instance.flagstring[3] = MainManager.itemdata[0, array2[2], 3];
				}
				MainManager.DialogueText("|showmoney|" + MainManager.map.dialogues[101] + "|next||goto," + ((array2[2] == -1) ? 103 : 102) + "|", call.transform, call);
				while (MainManager.instance.message)
