				}
				MainManager.UpdateJounal(MainManager.Library.Recipes, id);
				break;
			}
			case 1:
			{
				MainManager.instance.flagvar[0] = r;
				MainManager.instance.flagvar[1] = MainManager.instance.flagvar[0] * 5;
				MainManager.DialogueText("|showmoney|" + MainManager.map.dialogues[105] + "|prompt,yesno,-11,106|", call.transform, call);
				while (MainManager.instance.message)
				{
					yield return null;
				}
				if (MainManager.instance.option != 0)
