			while (MainManager.instance.message)
			{
				yield return null;
			}
			MainManager.instance.flags[706] = true;
		}
		else
		{
			MainManager.DialogueText(def + "|tail,delilah,instant|" + MainManager.map.dialogues[96] + "|prompt,yesno,97,98|", null, null);
			while (MainManager.instance.message)
			{
				yield return null;
			}
			if (MainManager.instance.option == 0)
			{
				MainManager.battlelossevent = true;
				StartCoroutine(BattleControl.StartBattle(new int[2] { 111, 112 }, 67, -1, "Bounty", null, true));
				while (MainManager.battle == null || !MainManager.battle.halfload)
				{
					yield return null;
				}
				MainManager.battle.battlemap.transform.GetChild(0).GetChild(2).gameObject.SetActive(false);
				yield return sec;
				while (MainManager.battle != null)
				{
					yield return null;
				}
				MainManager.GetEntity(17).animstate = 0;
				if (!MainManager.battleresult)
				{
					for (int i = 0; i < MainManager.instance.playerdata.Length; i++)
					{
						MainManager.instance.playerdata[i].entity.animstate = 17;
					}
					MainManager.InventoryFromString(item, 0, false);
				}
				else
				{
					for (int j = 0; j < MainManager.instance.playerdata.Length; j++)
					{
						MainManager.instance.playerdata[j].entity.animstate = 13;
					}
				}
				MainManager.SetCameraInstant(new Vector3(0.5f, 0.5f, -5f));
				yield return null;
				MainManager.battlelossevent = false;
				MainManager.ChangeMusic(0);
				MainManager.FadeOut();
				yield return sec;
				if (!MainManager.battleresult)
				{
					MainManager.DialogueText(def + "|tail,-4,instant|" + MainManager.map.dialogues[99] + "|minibubble,100,stratos||breakend|", null, null);
				}
				else
				{
					MainManager.DialogueText(def + "|tail,stratos,instant|" + MainManager.map.dialogues[101] + "|break||giveitem,-1,75,102|", null, null);
					MainManager.instance.flags[710] = true;
				}
				while (MainManager.instance.message)
				{
					yield return null;
				}
				if (!MainManager.instance.flags[707] && !MainManager.battlefled)
				{
					MainManager.CompleteQuest(63);
					MainManager.instance.flags[707] = true;
				}
			}
		}
		MainManager.ResetCamera();
		yield return null;
		EndEvent();
	}

