	private IEnumerator Event227()
	{
		EntityControl c = MainManager.map.entities[4];
		while (MainManager.instance.message)
		{
			yield return null;
		}
		if (!MainManager.instance.flags[722])
		{
			MainManager.DialogueText(MainManager.map.dialogues[36], c.transform, c.npcdata);
			while (MainManager.instance.message)
			{
				yield return null;
			}
		}
		int flags = MainManager.instance.flagvar[68];
		MainManager.FadeIn(0.05f);
		MainManager.FadeMusic(0.05f);
		yield return sec;
		yield return sec;
		MainManager.SetCameraInstant(new Vector3(0f, 1000f));
		FishingMain fish = UnityEngine.Object.Instantiate(Resources.Load<FishingMain>("Prefabs/Fishing/FishingMain"));
		fish.transform.parent = MainManager.GUICamera.transform;
		fish.transform.localEulerAngles = Vector3.zero;
		fish.transform.localPosition = new Vector3(0f, -1f, 15f);
		yield return null;
		MainManager.FadeOut(0.05f);
		yield return sec;
		fish.SetUp();
		while (fish != null)
		{
			yield return null;
		}
		MainManager.ResetCamera(true);
		yield return null;
		MainManager.FadeOut(0.05f);
		yield return sec;
		if (!MainManager.instance.flags[722] && MainManager.instance.flagvar[1] > 0)
		{
			MainManager.DialogueText(MainManager.map.dialogues[32], c.transform, c.npcdata);
			while (MainManager.instance.message)
			{
				yield return null;
			}
			MainManager.instance.flags[722] = true;
			EndEvent();
			yield break;
		}
		int newFish = 0;
		int total = 0;
		for (int i = 0; i < FishingMain.idKeys.Count; i++)
		{
			bool flag = ((uint)MainManager.instance.flagvar[68] & (uint)FishingMain.idKeys[i]) != 0;
			if (((uint)flags & (uint)FishingMain.idKeys[i]) == 0 && flag)
			{
				newFish++;
			}
			if (flag)
			{
				total++;
			}
		}
		int prize = newFish * 20 + MainManager.instance.flagvar[1] + MainManager.instance.flagvar[2];
		if (newFish > 0 && total == 10)
		{
			MainManager.DialogueText(MainManager.map.dialogues[30], c.transform, c.npcdata);
			while (MainManager.instance.message)
			{
				yield return null;
			}
			GiveItem(-1, prize + 30);
			MainManager.instance.flags[723] = true;
		}
		else if (newFish > 0)
		{
			MainManager.DialogueText(MainManager.map.dialogues[29], c.transform, c.npcdata);
			while (MainManager.instance.message)
			{
				yield return null;
			}
			GiveItem(-1, prize);
		}
		else
		{
			MainManager.DialogueText(MainManager.map.dialogues[28], c.transform, c.npcdata);
			if (prize > 0)
			{
				while (MainManager.instance.message)
				{
					yield return null;
				}
				GiveItem(-1, prize);
			}
		}
		while (MainManager.instance.message)
		{
			yield return null;
		}
		if (newFish > 0 && total >= 6 && !MainManager.instance.flags[721])
		{
			yield return halfsec;
			MainManager.instance.flags[721] = true;
			GiveItem(2, 82);
			while (MainManager.instance.message)
			{
				yield return null;
			}
		}
		yield return null;
		EndEvent();
	}

	private IEnumerator Event228()
	{
		while (MainManager.instance.message)
		{
			yield return null;
		}
		FishingMain.CreateString();
		Transform box = MainManager.Create9Box(new Vector3(5.5f, -1.5f, 5f), new Vector2(5f, 5f), 2, 10, Color.white, true);
		SpriteRenderer fishSprite = new GameObject("fish").AddComponent<SpriteRenderer>();
		MainManager.SetParenting(fishSprite.transform, box);
		fishSprite.gameObject.layer = 5;
		fishSprite.sortingOrder = 100;
		fishSprite.transform.localScale = Vector3.one * 2f;
		float[][] records = FishingMain.GetFishRecords();
		string[] array = FishingMain.LoadText();
		string text = "|boxstyle,3||face,party,caller|";
		MainManager.instance.flagvar[0] = -1;
		for (int i = 0; i < 10; i++)
		{
			text += "|spd,0|";
			text = ((!(records[i][0] > 0f)) ? (text + MainManager.menutext[59]) : (text + array[12].Replace("@NAME@", array[13 + i]).Replace("@SIZE@", records[i][1].ToString("0.00")).Replace("@AMT@", string.Concat(records[i][0]))));
			text += "|addvar,0,1|";
			if (i + 1 < 10)
			{
				text += "|next|";
			}
		}
		Sprite[] fs = Resources.LoadAll<Sprite>("Sprites/Misc/Fishing/fish");
		MainManager.DialogueText(text, call.transform, call);
		int c = -1;
		int[] fishSprites = new int[10] { 4, 13, 18, 53, 47, 40, 75, 73, 74, 72 };
		while (MainManager.instance.message)
		{
			if (c != MainManager.instance.flagvar[0])
			{
				c = MainManager.instance.flagvar[0];
				if (records[c][0] > 0f)
				{
					fishSprite.sprite = fs[fishSprites[c]];
				}
				else
				{
					fishSprite.sprite = MainManager.guisprites[171];
				}
			}
			yield return null;
		}
		for (float a = 0f; a < 10f; a += MainManager.framestep)
		{
			box.transform.localScale = Vector3.Lerp(Vector3.one, Vector3.zero, a / 10f);
			yield return null;
		}
		UnityEngine.Object.Destroy(box.gameObject);
		yield return null;
		EndEvent();
	}
